import static org.junit.Assert.assertSame;

/**
 * Unit tests for FastDateFormat.getDateTimeInstance
 */
public class FastDateFormat_getDateTimeInstance_TriageGen1Test {

    @Test
    public void testGetDateTimeInstance_WithAllParameters() {
        int dateStyle = Calendar.LONG;
        int timeStyle = Calendar.SHORT;
        TimeZone timeZone = TimeZone.getTimeZone("UTC");
        Locale locale = Locale.US;

        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        assertNotNull("Format should not be null", format);
        assertEquals("TimeZone should match", timeZone, format.getTimeZone());
        assertEquals("Locale should match", locale, format.getLocale());
    }

    @Test
    public void testGetDateTimeInstance_WithNullTimeZone() {
        int dateStyle = Calendar.MEDIUM;
        int timeStyle = Calendar.MEDIUM;
        TimeZone timeZone = null;
        Locale locale = Locale.GERMANY;

        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        assertNotNull("Format should not be null", format);
        assertEquals("Locale should match", locale, format.getLocale());
        // Since timeZone was null, the internal key construction skips the timeZone Pair.
        // The resulting format will use the default timezone of the system or specified in the instance.
    }

    @Test
    public void testGetDateTimeInstance_WithNullLocale() {
        int dateStyle = Calendar.SHORT;
        int timeStyle = Calendar.SHORT;
        TimeZone timeZone = TimeZone.getTimeZone("GMT");
        Locale locale = null;

        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        assertNotNull("Format should not be null", format);
        // When locale is null, it should fallback to Locale.getDefault()
        assertEquals("Locale should fallback to default", Locale.getDefault(), format.getLocale());
    }

    @Test
    public void testGetDateTimeInstance_CachingBehavior() {
        int dateStyle = Calendar.FULL;
        int timeStyle = Calendar.FULL;
        TimeZone timeZone = TimeZone.getTimeZone("Asia/Tokyo");
        Locale locale = Locale.JAPAN;

        // First call to populate cache
        FastDateFormat format1 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        // Second call with identical parameters
        FastDateFormat format2 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        assertNotNull(format1);
        assertNotNull(format2);
        assertSame("Subsequent calls with same parameters must return the same instance from cache", format1, format2);
    }

    @Test
    public void testGetDateTimeInstance_DifferentParameters() {
        int dateStyle1 = Calendar.SHORT;
        int timeStyle1 = Calendar.SHORT;
        TimeZone tz1 = TimeZone.getTimeZone("UTC");
        Locale loc1 = Locale.US;

        int dateStyle2 = Calendar.LONG;
        int timeStyle2 = Calendar.LONG;
        TimeZone tz2 = TimeZone.getTimeZone("America/New_York");
        Locale loc2 = Locale.FRANCE;

        FastDateFormat format1 = FastDateFormat.getDateTimeInstance(dateStyle1, timeStyle1, tz1, loc1);
        FastDateFormat format2 = FastDateFormat.getDateTimeInstance(dateStyle2, timeStyle2, tz2, loc2);

        assertNotNull(format1);
        assertNotNull(format2);
        // They should be different instances due to different cache keys
        org.junit.Assert.assertNotSame("Different parameters should yield different instances", format1, format2);
    }
}
